  d < fm_b FAM - 1 -> r < 2 + 1 ->
  lr_lhs (iarm_0RB0LA_1RC0RD_1LA1LC_1RC1RD d r)
    = cls_conf FAM (cls_side FAM [] (fm_b FAM - 1) r
                      (astride 2 1 r) [d]).
Proof.
  intros d r Hd Hr. vm_compute in Hd.
