(* arm2: NO KERNEL CHAIN -- no chain found *)
(* B[0] L<> R<0^1+y0 1^1+y1 0^1+y2 1^1+y3 #^1>  ==>  B[0] L<> R<1^1 0^y0 1^1+y1 0^1+y2 1^1+y3 #^1>   [4 steps] *)
Definition arm8_0RB0LA_1RC1RB_1LA0LD_0RB1LD : LRule :=
  mkLRule (mkC StB (mkS [] [] 0 0 []) S0 (mkS [S0] [] 0 0 []))
          (mkC StB (mkS [S0] [] 0 0 []) S0 (mkS [S1] [] 0 0 [])) 0 4.
Definition ch_arm8_0RB0LA_1RC1RB_1LA0LD_0RB1LD : list rstep := [RB (SWin 2);RB (SWinL 2)].
Lemma ok_arm8_0RB0LA_1RC1RB_1LA0LD_0RB1LD :
  check_arm tm true false rules arm8_0RB0LA_1RC1RB_1LA0LD_0RB1LD ch_arm8_0RB0LA_1RC1RB_1LA0LD_0RB1LD = true.
Proof. vm_compute. reflexivity. Qed.
