Proof. eapply arm_sound; [exact rules_sound_0RB0LA_1RC1RB_1LA0LD_0RB1LD | exact ok_arm8_0RB0LA_1RC1RB_1LA0LD_0RB1LD]. Qed.

(** ** What this board establishes

    7 of 9 arms of the certificate are re-derived by the kernel and
    sound: each [sound_*] is a theorem that the machine, from that arm's
    left-hand side and against any tail the flags permit, reaches the arm's
    right-hand side in exactly the certificate's step count. *)

(** ** The closure: from the RULES to [NeverQuasiHaltsSt]

    The arms below are the case split of [LadderCheck.digs_decomp], built
    from the FAMILY rather than mined: interior arms for the digits below the
    top, and fill arms.  Every certificate arm above is one of these with its
    run lengths pinned to their lower bounds, which is why 9 of them
    collapse to 5 here.

    Both classes are indexed by [LadderCheck]'s ONE arm scheme -- flat below
    a threshold, residue-and-stride at or above it.  The interior class runs
    at threshold 2 stride 1, the fill class at threshold 2
    stride 1.

    [board_neverqh] consumes them, the boot, and one chain per state per fill
    arm, and returns the machine-level theorem. *)

(** *** The inner rules: what the nested arms iterate

    2 rule(s), validated like the ladder at both tails opaque. *)
Definition nlad_0RB0LA_1RC1RB_1LA0LD_0RB1LD : list (LRule * list rstep) :=
  [(mkLRule (mkC StD (mkS [] [] 0 0 []) S0 (mkS [S1] [S1] 1 0 [S0;S1])) (mkC StD (mkS [] [] 0 0 []) S0 (mkS [S1] [S1] 1 1 [S0])) 2 6, [RB (SWin 1);RB (SCycR 1);RB (SWin 4);RB (SCycL 1 0);RB (SWin 1);RB (SRotR 1);RB (SFoldR 1)]);
   (mkLRule (mkC StD (mkS [] [] 0 0 []) S0 (mkS [S1] [S1] 1 0 [S0;S1])) (mkC StD (mkS [] [] 0 0 []) S0 (mkS [S1] [S1] 1 1 [S0])) 2 6, [RB (SWin 1);RB (SCycR 1);RB (SWin 4);RB (SCycL 1 0);RB (SWin 1);RB (SRotR 1);RB (SFoldR 1)])].
Definition nrules_0RB0LA_1RC1RB_1LA0LD_0RB1LD : list LRule := map fst nlad_0RB0LA_1RC1RB_1LA0LD_0RB1LD.
Local Notation nrules := nrules_0RB0LA_1RC1RB_1LA0LD_0RB1LD.

Lemma nladder_ok_0RB0LA_1RC1RB_1LA0LD_0RB1LD : check_ladder tm [] nlad_0RB0LA_1RC1RB_1LA0LD_0RB1LD = true.
Proof. vm_compute. reflexivity. Qed.

Lemma nrules_sound_0RB0LA_1RC1RB_1LA0LD_0RB1LD : Forall (RuleSound tm false false) nrules.
Proof. apply rule_sound_nil. exact nladder_ok_0RB0LA_1RC1RB_1LA0LD_0RB1LD. Qed.

Definition iarm0_0_0RB0LA_1RC1RB_1LA0LD_0RB1LD : LRule :=
  mkLRule (mkC StB (mkS [] [] 0 0 []) S0 (mkS [S0] [] 0 0 []))
          (mkC StB (mkS [] [] 0 0 []) S0 (mkS [S1] [] 0 0 [])) 0 1.
Definition ch_iarm0_0_0RB0LA_1RC1RB_1LA0LD_0RB1LD : list nseg :=
