          (mkC StB (mkS [] [] 0 0 []) S0 (mkS [S0;S1] [] 0 0 [])) 0 1.
Definition ch_iarm0_1_0RB0LA_1RC1RB_1LA0LD_0RB1LD : list nseg :=
  [NCh [RB (SWin 2);RB (SWinL 8)]].
