Definition iarm0_2_0RB0LA_1RC1RB_1LA0LD_0RB1LD : LRule :=
  mkLRule (mkC StB (mkS [] [] 0 0 []) S0 (mkS [S1;S1] [S1] 1 0 [S0]))
          (mkC StB (mkS [] [] 0 0 []) S0 (mkS [S0;S0] [S0] 1 0 [S1])) 0 1.
