Lemma vis_ok_0RB0LA_1RC1RB_1LA0LD_0RB1LD : forall r t, ~ In t pins_0RB0LA_1RC1RB_1LA0LD_0RB1LD -> 0 < r ->
  r < 2 + 1 ->
  nfire tm true true nrules (vsegs_0RB0LA_1RC1RB_1LA0LD_0RB1LD r t) (vis_0RB0LA_1RC1RB_1LA0LD_0RB1LD r t)
    (lr_lhs (farm_0RB0LA_1RC1RB_1LA0LD_0RB1LD r 0)) = Some t.
Proof.
  intros r t Hnp H0 Hr.
  destruct r as [|r].
  { exfalso; lia. }
  destruct r as [|r].
  { destruct t as [q s]; destruct q, s; try (exfalso; apply Hnp; simpl; tauto); vm_compute; reflexivity. }
  destruct r as [|r].
  { destruct t as [q s]; destruct q, s; try (exfalso; apply Hnp; simpl; tauto); vm_compute; reflexivity. }
  exfalso; lia.
Qed.

Lemma bootl_0RB0LA_1RC1RB_1LA0LD_0RB1LD :
  stepn tm 5 InitES = Some (lift (fam_cfg FAM ([1], 0, 0))).
Proof.
  assert (H : match csteps tm 5 c0 with
              | Some c => ceqb c (fam_cfg FAM ([1], 0, 0))
              | None => false end = true) by (vm_compute; reflexivity).
  destruct (csteps tm 5 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** The machine-level theorem, at the INSTRUCTION level, through the nested
    board [LadderCheckNestTr.boardN_neverqhtr]. *)
Theorem nqhtr_0RB0LA_1RC1RB_1LA0LD_0RB1LD : NeverQuasiHaltsTr tm_0RB0LA_1RC1RB_1LA0LD_0RB1LD.
Proof.
  eapply (boardN_neverqhtr tm_0RB0LA_1RC1RB_1LA0LD_0RB1LD pins_0RB0LA_1RC1RB_1LA0LD_0RB1LD FAM 1
                           iarm_0RB0LA_1RC1RB_1LA0LD_0RB1LD 2 1
                           farm_0RB0LA_1RC1RB_1LA0LD_0RB1LD 2 1
                           fm1_0RB0LA_1RC1RB_1LA0LD_0RB1LD fm2_0RB0LA_1RC1RB_1LA0LD_0RB1LD 0
                           nrules vsegs_0RB0LA_1RC1RB_1LA0LD_0RB1LD vis_0RB0LA_1RC1RB_1LA0LD_0RB1LD
                           [1] 0).
  - vm_compute; lia.
  - vm_compute; reflexivity.
  - vm_compute; reflexivity.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; lia. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; lia. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; lia. }
    exfalso; lia.
  - lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { exists 0; vm_compute; reflexivity. }
    exfalso; lia.
  - exact fm12_0RB0LA_1RC1RB_1LA0LD_0RB1LD.
