              | None => false end = true) by (vm_compute; reflexivity).
  destruct (csteps tm 6 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** The machine-level theorem, at the INSTRUCTION level, through the nested
    board [LadderCheckNestTr.boardN_neverqhtr]. *)
Theorem nqhtr_0RB0LC_1RC1RD_1LB0LA_1LC0RD : NeverQuasiHaltsTr tm_0RB0LC_1RC1RD_1LB0LA_1LC0RD.
Proof.
  eapply (boardN_neverqhtr tm_0RB0LC_1RC1RD_1LB0LA_1LC0RD pins_0RB0LC_1RC1RD_1LB0LA_1LC0RD FAM 1
                           iarm_0RB0LC_1RC1RD_1LB0LA_1LC0RD 0 2
