                           fm1_0RB0LC_1RC1RD_1LB0LA_1LC0RD fm2_0RB0LC_1RC1RD_1LB0LA_1LC0RD 0
                           nrules vsegs_0RB0LC_1RC1RD_1LB0LA_1LC0RD vis_0RB0LC_1RC1RD_1LB0LA_1LC0RD
                           [1] 0).
  - vm_compute; lia.
  - vm_compute; reflexivity.
  - vm_compute; reflexivity.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; lia. }
    exfalso; lia.
  - intros ph Hph.
