(* C[1] L<0^1+y0 1^1+y1 0^1+y2 1^1+y3 #^1> R<1^1>  ==>  C[1] L<1^1 0^y0 1^1+y1 0^1+y2 1^1+y3 #^1> R<1^1>   [12 steps] *)
Definition arm8_0RB1LA_1LC1RB_1RD0LA_0LB0RD : LRule :=
  mkLRule (mkC StC (mkS [S0] [] 0 0 []) S1 (mkS [S1] [] 0 0 []))
          (mkC StC (mkS [S1] [] 0 0 []) S1 (mkS [S1;S0] [] 0 0 [])) 0 12.
Definition ch_arm8_0RB1LA_1LC1RB_1RD0LA_0LB0RD : list rstep := [RB (SWin 5);RB (SWinR 7)].
