Definition iarm_1RB0LD_1LC0RB_0RA0LC_1LD1RA (d r : nat) : LRule :=
  match d, r with
  | 0, 0 => iarm0_0_1RB0LD_1LC0RB_0RA0LC_1LD1RA
  | 0, 1 => iarm0_1_1RB0LD_1LC0RB_0RA0LC_1LD1RA
  | 0, 2 => iarm0_2_1RB0LD_1LC0RB_0RA0LC_1LD1RA
  | 0, 3 => iarm0_3_1RB0LD_1LC0RB_0RA0LC_1LD1RA
  | _, _ => iarm0_0_1RB0LD_1LC0RB_0RA0LC_1LD1RA   (* unreachable: only d < b-1 and r < N0 + st *)
  end.

(** The fill arms, one per arm index and PHASE.  Both tails are known
    empty -- they are the only arms that see the end of the counter -- and
    the arm at index [r] has [r] guaranteed block copies materialised into
    [s_pre], without which it has no chain at all.  [fm1]/[fm2] say how the
    fill target's own guaranteed copies divide about the block.

    The phase is the second index because the fill arm is the ONLY one that
    sees a terminator: it leaves from the terminator of its own phase and
    lands on the terminator of the phase its law names.  The interior arms
    keep the terminator in the opaque tail and are phase-free. *)
Definition farm_1RB0LD_1LC0RB_0RA0LC_1LD1RA (r ph : nat) : LRule :=
  match r, ph with
  | 1, 0 => farm1_0_1RB0LD_1LC0RB_0RA0LC_1LD1RA
  | 2, 0 => farm2_0_1RB0LD_1LC0RB_0RA0LC_1LD1RA
  | 3, 0 => farm3_0_1RB0LD_1LC0RB_0RA0LC_1LD1RA
  | _, _ => farm1_0_1RB0LD_1LC0RB_0RA0LC_1LD1RA  (* unreachable: 0 < r < N0 + st *)
  end.

Definition fm1_1RB0LD_1LC0RB_0RA0LC_1LD1RA (r ph : nat) : nat :=
  match r, ph with | 1, 0 => 1 | 2, 0 => 1 | 3, 0 => 1 | _, _ => 0 end.
Definition fm2_1RB0LD_1LC0RB_0RA0LC_1LD1RA (r ph : nat) : nat :=
