Definition iarm_1RB0RB_1RC1RB_1LD1LC_0RA0LD (d r : nat) : LRule :=
  match d, r with
  | 0, 0 => iarm0_0_1RB0RB_1RC1RB_1LD1LC_0RA0LD
  | 0, 1 => iarm0_1_1RB0RB_1RC1RB_1LD1LC_0RA0LD
  | 0, 2 => iarm0_2_1RB0RB_1RC1RB_1LD1LC_0RA0LD
  | _, _ => iarm0_0_1RB0RB_1RC1RB_1LD1LC_0RA0LD   (* unreachable: only d < b-1 and r < N0 + st *)
  end.

(** The fill arms, one per arm index and PHASE.  Both tails are known
    empty -- they are the only arms that see the end of the counter -- and
    the arm at index [r] has [r] guaranteed block copies materialised into
    [s_pre], without which it has no chain at all.  [fm1]/[fm2] say how the
    fill target's own guaranteed copies divide about the block.

    The phase is the second index because the fill arm is the ONLY one that
    sees a terminator: it leaves from the terminator of its own phase and
    lands on the terminator of the phase its law names.  The interior arms
    keep the terminator in the opaque tail and are phase-free. *)
Definition farm_1RB0RB_1RC1RB_1LD1LC_0RA0LD (r ph : nat) : LRule :=
  match r, ph with
  | 1, 0 => farm1_0_1RB0RB_1RC1RB_1LD1LC_0RA0LD
  | 2, 0 => farm2_0_1RB0RB_1RC1RB_1LD1LC_0RA0LD
  | _, _ => farm1_0_1RB0RB_1RC1RB_1LD1LC_0RA0LD  (* unreachable: 0 < r < N0 + st *)
  end.

Definition fm1_1RB0RB_1RC1RB_1LD1LC_0RA0LD (r ph : nat) : nat :=
  match r, ph with | 1, 0 => 1 | 2, 0 => 1 | _, _ => 0 end.
Definition fm2_1RB0RB_1RC1RB_1LD1LC_0RA0LD (r ph : nat) : nat :=
  match r, ph with | 1, 0 => 0 | 2, 0 => 1 | _, _ => 0 end.

(** One chain per UNPINNED INSTRUCTION per fill arm, at the VISIT PHASE
    0.  [fire_of_run_instr] turns each into a fire of that instruction,
    and [tops_cofinal_at] says the tops of that phase keep coming.  The fill
    arm is the counter's overflow, so this is where the rare instruction of
    a sparse row is witnessed. *)
Definition vis_1RB0RB_1RC1RB_1LD1LC_0RA0LD (r : nat) (t : Instr) : list lstep :=
  match r, t with
  | 1, (StA, S0) => [SWin 0]
  | 1, (StA, S1) => [SWinL 7]
  | 1, (StB, S0) => [SWin 1]
  | 1, (StB, S1) => [SWinL 8]
  | 1, (StC, S0) => [SWinL 5]
  | 1, (StC, S1) => [SWin 2]
  | 1, (StD, S0) => [SWinL 6]
  | 1, (StD, S1) => [SWin 4;SWinL 6;SWinR 3]
  | 2, (StA, S0) => [SWin 0]
  | 2, (StA, S1) => [SWinL 7]
  | 2, (StB, S0) => [SWin 1]
  | 2, (StB, S1) => [SWinL 8]
  | 2, (StC, S0) => [SWinL 5]
  | 2, (StC, S1) => [SWin 2]
  | 2, (StD, S0) => [SWinL 6]
  | 2, (StD, S1) => [SWin 1;SCycR 1;SWinR 3]
  | _, _ => []
  end.

(** ...each after its segment program: a visit that fires past the rounds
    of a nested fill arm first runs that arm's program up to them. *)
Definition vsegs_1RB0RB_1RC1RB_1LD1LC_0RA0LD (r : nat) (t : Instr) : list nseg :=
  match r, t with
  | 1, (StA, S0) => []
  | 1, (StA, S1) => []
  | 1, (StB, S0) => []
  | 1, (StB, S1) => []
  | 1, (StC, S0) => []
  | 1, (StC, S1) => []
  | 1, (StD, S0) => []
  | 1, (StD, S1) => []
  | 2, (StA, S0) => []
  | 2, (StA, S1) => []
  | 2, (StB, S0) => []
  | 2, (StB, S1) => []
  | 2, (StC, S0) => []
  | 2, (StC, S1) => []
  | 2, (StD, S0) => []
  | 2, (StD, S1) => [NCh [RB (SWin 4);RB (SWinL 3)]; NUp 1 [] [S0;S1] 1 1 0 (mkS [] [] 0 0 []) (mkS [] [] 0 0 []) true]
  | _, _ => []
  end.

Lemma iarm_reach_1RB0RB_1RC1RB_1LD1LC_0RA0LD : forall d r,
  d < fm_b FAM - 1 -> r < 2 + 1 ->
  ReachL tm (negb (fm_left FAM)) (fm_left FAM)
    (lr_lhs (iarm_1RB0RB_1RC1RB_1LD1LC_0RA0LD d r)) (lr_rhs (iarm_1RB0RB_1RC1RB_1LD1LC_0RA0LD d r)).
Proof.
  intros d r Hd Hr. vm_compute in Hd.
  destruct d as [|d].
  {
    destruct r as [|r].
    { eapply narm_reach; [exact nrules_sound_1RB0RB_1RC1RB_1LD1LC_0RA0LD | exact ok_iarm0_0_1RB0RB_1RC1RB_1LD1LC_0RA0LD]. }
    destruct r as [|r].
    { eapply narm_reach; [exact nrules_sound_1RB0RB_1RC1RB_1LD1LC_0RA0LD | exact ok_iarm0_1_1RB0RB_1RC1RB_1LD1LC_0RA0LD]. }
    destruct r as [|r].
    { eapply narm_reach; [exact nrules_sound_1RB0RB_1RC1RB_1LD1LC_0RA0LD | exact ok_iarm0_2_1RB0RB_1RC1RB_1LD1LC_0RA0LD]. }
    exfalso; lia.
  }
  exfalso; lia.
Qed.

