    keep the terminator in the opaque tail and are phase-free. *)
Definition farm_1RB1RA_0LC0RB_0LD1LC_1LA1RD (r ph : nat) : LRule :=
  match r, ph with
  | 1, 0 => farm1_0_1RB1RA_0LC0RB_0LD1LC_1LA1RD
  | 1, 1 => farm1_1_1RB1RA_0LC0RB_0LD1LC_1LA1RD
  | _, _ => farm1_0_1RB1RA_0LC0RB_0LD1LC_1LA1RD  (* unreachable: 0 < r < N0 + st *)
  end.

