(* arm14: NO KERNEL CHAIN -- no chain found *)
(* C[0] L<0^2+y0 01^1+y1 0^2+y2 01^1+y3 #^1> R<>  ==>  C[0] L<0^1 1^1 0^y0 01^1+y1 0^2+y2 01^1+y3 #^1> R<>   [6 steps] *)
Definition arm15_1RB1RA_0LC0RB_1LD0LD_1LA1LD : LRule :=
  mkLRule (mkC StC (mkS [S0;S0] [] 0 0 []) S0 (mkS [] [] 0 0 []))
          (mkC StC (mkS [S0;S1] [] 0 0 []) S0 (mkS [S0] [] 0 0 [])) 0 6.
Definition ch_arm15_1RB1RA_0LC0RB_1LD0LD_1LA1LD : list rstep := [RB (SWin 4);RB (SWinR 2)].
