  match r, ph with
  | 1, 0 => farm1_0_1RB1RA_1LC0LD_0RA0LC_0RA1LD
  | 2, 0 => farm2_0_1RB1RA_1LC0LD_0RA0LC_0RA1LD
  | _, _ => farm1_0_1RB1RA_1LC0LD_0RA0LC_0RA1LD  (* unreachable: 0 < r < N0 + st *)
  end.

