Lemma vis_ok_1RB1RA_1LC0LD_0RA0LC_0RB1LD : forall r t, ~ In t pins_1RB1RA_1LC0LD_0RA0LC_0RB1LD -> 0 < r ->
  r < 2 + 1 ->
