  exfalso; lia.
Qed.

Lemma bootl_1RB1RA_1LC0LD_0RA0LC_0RB1LD :
  stepn tm 4 InitES = Some (lift (fam_cfg FAM ([1], 0, 0))).
Proof.
  assert (H : match csteps tm 4 c0 with
              | Some c => ceqb c (fam_cfg FAM ([1], 0, 0))
              | None => false end = true) by (vm_compute; reflexivity).
  destruct (csteps tm 4 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** The machine-level theorem, at the INSTRUCTION level, through the nested
    board [LadderCheckNestTr.boardN_neverqhtr]. *)
Theorem nqhtr_1RB1RA_1LC0LD_0RA0LC_0RB1LD : NeverQuasiHaltsTr tm_1RB1RA_1LC0LD_0RA0LC_0RB1LD.
Proof.
  eapply (boardN_neverqhtr tm_1RB1RA_1LC0LD_0RA0LC_0RB1LD pins_1RB1RA_1LC0LD_0RA0LC_0RB1LD FAM 1
                           iarm_1RB1RA_1LC0LD_0RA0LC_0RB1LD 2 1
