(** ** What this board establishes

    10 of 13 arms of the certificate are re-derived by the kernel and
    sound: each [sound_*] is a theorem that the machine, from that arm's
    left-hand side and against any tail the flags permit, reaches the arm's
    right-hand side in exactly the certificate's step count. *)

(** ** The closure: from the RULES to [NeverQuasiHaltsSt]

    The arms below are the case split of [LadderCheck.digs_decomp], built
    from the FAMILY rather than mined: interior arms for the digits below the
    top, and fill arms.  Every certificate arm above is one of these with its
    run lengths pinned to their lower bounds, which is why 13 of them
    collapse to 7 here.

    Both classes are indexed by [LadderCheck]'s ONE arm scheme -- flat below
    a threshold, residue-and-stride at or above it.  The interior class runs
    at threshold 2 stride 1, the fill class at threshold 2
    stride 1.

    [board_neverqh] consumes them, the boot, and one chain per state per fill
    arm, and returns the machine-level theorem. *)

(** *** The inner rules: what the nested arms iterate

    3 rule(s), validated like the ladder at both tails opaque. *)
Definition nlad_1RB1RA_1RC0RA_1LD1LC_0RB0LD : list (LRule * list rstep) :=
  [(mkLRule (mkC StA (mkS [S1;S1] [S1] 3 0 [S0;S0]) S0 (mkS [S0;S1;S0] [] 0 0 [])) (mkC StA (mkS [S1;S1] [S1] 3 3 [S0;S0]) S0 (mkS [] [] 0 0 [])) 6 15, [RB (SWin 6);RB (SCycL 1 0);RB (SWin 4);RB (SCycR 1);RB (SWin 5);RB (SFoldL 1);RB (SFoldL 2)]);
   (mkLRule (mkC StA (mkS [S1;S1] [S1] 3 0 [S0;S0]) S0 (mkS [S0;S1;S0] [] 0 0 [])) (mkC StA (mkS [S1;S1] [S1] 3 3 [S0;S0]) S0 (mkS [] [] 0 0 [])) 6 15, [RB (SWin 6);RB (SCycL 1 0);RB (SWin 4);RB (SCycR 1);RB (SWin 5);RB (SFoldL 1);RB (SFoldL 2)]);
   (mkLRule (mkC StA (mkS [S1;S1] [S1] 3 0 [S0;S0]) S0 (mkS [S0;S1;S0] [] 0 0 [])) (mkC StA (mkS [S1;S1] [S1] 3 3 [S0;S0]) S0 (mkS [] [] 0 0 [])) 6 15, [RB (SWin 6);RB (SCycL 1 0);RB (SWin 4);RB (SCycR 1);RB (SWin 5);RB (SFoldL 1);RB (SFoldL 2)])].
Definition nrules_1RB1RA_1RC0RA_1LD1LC_0RB0LD : list LRule := map fst nlad_1RB1RA_1RC0RA_1LD1LC_0RB0LD.
Local Notation nrules := nrules_1RB1RA_1RC0RA_1LD1LC_0RB0LD.

Lemma nladder_ok_1RB1RA_1RC0RA_1LD1LC_0RB0LD : check_ladder tm [] nlad_1RB1RA_1RC0RA_1LD1LC_0RB0LD = true.
Proof. vm_compute. reflexivity. Qed.

Lemma nrules_sound_1RB1RA_1RC0RA_1LD1LC_0RB0LD : Forall (RuleSound tm false false) nrules.
Proof. apply rule_sound_nil. exact nladder_ok_1RB1RA_1RC0RA_1LD1LC_0RB0LD. Qed.

