    destruct r as [|r].
    { eapply narm_reach; [exact nrules_sound_1RB1RA_1RC0RA_1LD1LC_0RB0LD | exact ok_iarm0_1_1RB1RA_1RC0RA_1LD1LC_0RB0LD]. }
    destruct r as [|r].
    { eapply narm_reach; [exact nrules_sound_1RB1RA_1RC0RA_1LD1LC_0RB0LD | exact ok_iarm0_2_1RB1RA_1RC0RA_1LD1LC_0RB0LD]. }
    exfalso; lia.
  }
  exfalso; lia.
Qed.

