Lemma bootl_1RB1RC_1LA0LD_1LB0RC_0RA0LB :
  stepn tm 5 InitES = Some (lift (fam_cfg FAM ([1], 0, 0))).
Proof.
  assert (H : match csteps tm 5 c0 with
              | Some c => ceqb c (fam_cfg FAM ([1], 0, 0))
              | None => false end = true) by (vm_compute; reflexivity).
  destruct (csteps tm 5 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** The machine-level theorem, at the INSTRUCTION level, through the nested
    board [LadderCheckNestTr.boardN_neverqhtr]. *)
Theorem nqhtr_1RB1RC_1LA0LD_1LB0RC_0RA0LB : NeverQuasiHaltsTr tm_1RB1RC_1LA0LD_1LB0RC_0RA0LB.
Proof.
  eapply (boardN_neverqhtr tm_1RB1RC_1LA0LD_1LB0RC_0RA0LB pins_1RB1RC_1LA0LD_1LB0RC_0RA0LB FAM 1
                           iarm_1RB1RC_1LA0LD_1LB0RC_0RA0LB 0 2
                           farm_1RB1RC_1LA0LD_1LB0RC_0RA0LB 1 2
                           fm1_1RB1RC_1LA0LD_1LB0RC_0RA0LB fm2_1RB1RC_1LA0LD_1LB0RC_0RA0LB 0
                           nrules vsegs_1RB1RC_1LA0LD_1LB0RC_0RA0LB vis_1RB1RC_1LA0LD_1LB0RC_0RA0LB
                           [1] 0).
  - vm_compute; lia.
  - vm_compute; reflexivity.
  - vm_compute; reflexivity.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    exfalso; lia.
  - intros ph Hph.
