    { vm_compute; lia. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; lia. }
    exfalso; lia.
  - lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { exists 0; vm_compute; reflexivity. }
    exfalso; lia.
  - exact fm12_1RB1RC_1LA0LD_1LB0RC_0RA0LB.
  - repeat constructor.
  - vm_compute; lia.
  - lia.
  - lia.
  - exact iarm_reach_1RB1RC_1LA0LD_1LB0RC_0RA0LB.
  - exact iarm_lhs_1RB1RC_1LA0LD_1LB0RC_0RA0LB.
  - exact iarm_rhs_1RB1RC_1LA0LD_1LB0RC_0RA0LB.
