  - exact farm_rhs_1RB1RC_1LA0LD_1LB0RC_0RA0LB.
  - exact nrules_sound_1RB1RC_1LA0LD_1LB0RC_0RA0LB.
  - exact vis_ok_1RB1RC_1LA0LD_1LB0RC_0RA0LB.
  - exact bootl_1RB1RC_1LA0LD_1LB0RC_0RA0LB.
Qed.

